{"content": """"
Subscription Registry — baseline implementation (no validation yet).

Feature A (validated subscribe) and Feature B (unsubscribe) are added
in later turns.
"""


class Registry:
    """In-memory subscription registry."""

    def __init__(self):
        self._subscribers: set[str] = set()

    def subscribe(self, name: str) -> bool:
        """Add *name* to the registry.

        Returns True if newly added, False if already present.
        No validation is applied in the baseline; validation arrives in A.
        """
        if name in self._subscribers:
            return False
        self._subscribers.add(name)
        return True

    def names(self) -> list[str]:
        """Return a sorted snapshot of all current subscribers."""
        return sorted(self._subscribers)
